"""Write the HTML named character references as an Emacs Lisp library.

Usage: python3 entities.py > agentel-commonmark-entities.el
"""

from html.entities import html5

HEADER = """\
;;; agentel-commonmark-entities.el --- HTML named character references  -*- lexical-binding: t; -*-

;; Copyright (C) 2026 Shinnosuke Sawada-Dazai
;; SPDX-License-Identifier: GPL-3.0-or-later

;;; Commentary:

;; The named character references of HTML, which CommonMark decodes.
;; Generated by etc/entities.py from the table of Python; do not edit.

;;; Code:

(defconst agentel-commonmark-entities
  (let ((table (make-hash-table :test #'equal :size {size})))
    (dolist (entity '(
"""

FOOTER = """\
                      ))
      (puthash (car entity) (cdr entity) table))
    table)
  "Map the name of an HTML character reference to the text it stands for.")

(provide 'agentel-commonmark-entities)
;;; agentel-commonmark-entities.el ends here
"""


def lisp_string(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"') + '"'


def main():
    names = sorted(name[:-1] for name in html5 if name.endswith(";"))
    print(HEADER.format(size=len(names)), end="")
    for name in names:
        print(f"                      ({lisp_string(name)} . {lisp_string(html5[name + ';'])})")
    print(FOOTER, end="")


if __name__ == "__main__":
    main()
